cypress_script:
describe('Product Image Alt-Texts and Accessible Form Fields', () => {
  it('should display product images with correct alt-texts', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    // Assert that product images have alt-texts
    cy.get('[data-test="item-0-title-link"]').should('be.visible');
    cy.get('[data-test="item-1-title-link"]').should('be.visible');
    cy.get('[data-test="item-2-title-link"]').should('be.visible');
    cy.get('[data-test="item-3-title-link"]').should('be.visible');
    cy.get('[data-test="item-4-title-link"]').should('be.visible');
    cy.get('[data-test="item-5-title-link"]').should('be.visible');
  });

  it('should not change URL when clicking on non-interactive elements', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    // Click on a product title link and assert that the URL does not change
    cy.get('[data-test="item-0-title-link"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Image Alt-Texts and Accessible Form Fields', () => {
  test('should display product images with correct alt-texts', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    // Assert that product images have alt-texts
    await expect(page.locator('[data-test="item-0-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-1-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-2-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-3-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-4-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-5-title-link"]')).toBeVisible();
  });

  test('should not change URL when clicking on non-interactive elements', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    // Click on a product title link and assert that the URL does not change
    await page.click('[data-test="item-0-title-link"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/inventory.html');
  });
});
